import { meetings } from '@/fixtures/meetings'
import { transcripts } from '@/fixtures/transcripts'
import { summaries, actionItems } from '@/fixtures/summaries'
import prisma from '@/lib/db'

export async function provisionDemoWorkspace(userId: string) {
  try {
    // Idempotency check: if user already has demo data, do nothing.
    const existing = await prisma.meeting.findFirst({
      where: { userId, id: { startsWith: 'demo-' } }
    })
    if (existing) return

    for (const m of meetings) {
      const newMeetingId = `demo-${userId}-${m.id}`

      await prisma.meeting.create({
        data: {
          id: newMeetingId,
          userId,
          title: m.title,
          date: new Date(m.date),
          duration: m.duration,
          status: m.status,
          mediaUrl: m.mediaUrl,
          attendees: {
            create: m.attendees.map(a => ({ name: a.name, avatar: a.avatar }))
          }
        }
      })

      // Seed Transcripts
      const meetingTranscripts = transcripts.filter(t => t.meetingId === m.id)
      if (meetingTranscripts.length > 0) {
        await prisma.transcriptLine.createMany({
          data: meetingTranscripts.map(t => ({
            meetingId: newMeetingId,
            speaker: t.speaker,
            text: t.text,
            startTime: t.startTime,
            endTime: t.endTime
          }))
        })
      }

      // Seed Summaries
      const meetingSummaries = summaries.filter(s => s.meetingId === m.id)
      if (meetingSummaries.length > 0) {
        await prisma.summary.createMany({
          data: meetingSummaries.map(s => ({
            meetingId: newMeetingId,
            template: s.template,
            contentMarkdown: s.contentMarkdown
          }))
        })
      }

      // Seed Action Items
      const meetingActions = actionItems.filter(a => a.meetingId === m.id)
      if (meetingActions.length > 0) {
        await prisma.actionItem.createMany({
          data: meetingActions.map(a => ({
            meetingId: newMeetingId,
            task: a.task,
            assignee: a.assignee,
            isCompleted: a.isCompleted
          }))
        })
      }
    }
    console.log(`Provisioned demo workspace for user ${userId}`)
  } catch (error) {
    console.error("Failed to provision demo workspace:", error)
  }
}

