"use client"
import React, { useState, useEffect, useRef } from "react"
import { useSearchParams } from "next/navigation"
import { usePlayerStore } from "@/store/player-store"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Checkbox } from "@/components/ui/checkbox"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Search, Loader2, Bot, ArrowLeft, Star, Clock } from "lucide-react"
import { motion, AnimatePresence } from "framer-motion"
import Link from "next/link"

export default function MeetingPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = React.use(params)
  const id = resolvedParams.id
  const searchParams = useSearchParams()
  const isLive = searchParams.get("live") === "true"

  const [meeting, setMeeting] = useState<any>(null)
  const [isOwner, setIsOwner] = useState(false)
  const [fullTranscript, setFullTranscript] = useState<any[]>([])
  const [meetingActionItems, setMeetingActionItems] = useState<any[]>([])
  const [currentSummary, setCurrentSummary] = useState<any>(null)

  const [activeTemplate, setActiveTemplate] = useState<string>("Standard")
  const [isGenerating, setIsGenerating] = useState(false)

  const { currentTime, setCurrentTime, isPlaying, setIsPlaying, seekRequest, clearSeekRequest } = usePlayerStore()
  const videoRef = useRef<HTMLVideoElement>(null)
  const activeLineRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const fetchData = async () => {
      const res = await fetch(`/api/meetings/${id}`)
      if (res.ok) {
        const data = await res.json()
        setMeeting(data.meeting)
        setIsOwner(data.isOwner)
        setFullTranscript(data.transcripts)
        setMeetingActionItems(data.actionItems)
        const summary = data.summaries.find((s: any) => s.template === activeTemplate)
        setCurrentSummary(summary)
      }
    }
    fetchData()

    if (isLive) {
      const timer = setTimeout(async () => {
        const res = await fetch('/api/simulate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ meetingId: id })
        })
        if (res.ok) {
          window.location.replace(`/meeting/${id}`)
        }
      }, 3500)
      return () => clearTimeout(timer)
    }
  }, [id, activeTemplate, isLive])

  const handleTemplateChange = async (val: string) => {
    setActiveTemplate(val)
    setIsGenerating(true)
    try {
      const res = await fetch('/api/summarize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ meetingId: id, templateType: val })
      })
      if (res.ok) {
        const data = await res.json()
        setCurrentSummary(data.summary)
        if (data.actionItems) setMeetingActionItems(data.actionItems)
      }
    } catch (err) {
      console.error("Summary error:", err)
    } finally {
      setIsGenerating(false)
    }
  }

  useEffect(() => {
    if (seekRequest !== null && videoRef.current && !isLive) {
      videoRef.current.currentTime = seekRequest
      clearSeekRequest()
    }
  }, [seekRequest, isLive, clearSeekRequest])

  const handleTimeUpdate = () => {
    if (videoRef.current) setCurrentTime(videoRef.current.currentTime)
  }

  useEffect(() => {
    if (activeLineRef.current && !isLive) {
      activeLineRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }
  }, [currentTime, isLive])

  const [chatInput, setChatInput] = useState("")
  const [chatMessages, setChatMessages] = useState<{role: 'user'|'ai', text: string}[]>([])
  const [isChatting, setIsChatting] = useState(false)

  const handleChat = async () => {
    if (!chatInput.trim()) return
    const msg = chatInput
    const currentHistory = [...chatMessages]

    setChatInput("")
    setChatMessages(prev => [...prev, { role: 'user', text: msg }])
    setIsChatting(true)

    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ meetingId: id, question: msg, history: currentHistory })
      })
      if (res.ok) {
        const data = await res.json()
        setChatMessages(prev => [...prev, { role: 'ai', text: data.reply }])
      }
    } catch (err) {
      setChatMessages(prev => [...prev, { role: 'ai', text: 'Sorry, I encountered an error answering that.' }])
    } finally {
      setIsChatting(false)
    }
  }

  const [toast, setToast] = useState<string | null>(null)
  const showToast = (msg: string) => {
    setToast(msg)
    setTimeout(() => setToast(null), 3000)
  }

  if (!meeting) return <div className="p-8 text-center text-slate-500 flex items-center justify-center h-screen bg-slate-50"><Loader2 className="w-8 h-8 animate-spin text-sky-600 mr-3" /> Loading meeting...</div>

  return (
    <div className="flex h-screen bg-white text-slate-900 overflow-hidden flex-col md:flex-row font-sans">

      {/* Left Column (Video + Transcript) */}
      <div className="flex-1 flex flex-col border-r border-slate-200 h-full overflow-hidden relative">
        {toast && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 bg-slate-900 text-white px-5 py-2.5 rounded-lg shadow-xl text-sm flex items-center font-medium">
            {toast}
          </div>
        )}

        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-white shrink-0">
          <div className="flex items-center gap-5">
            <Link href="/">
              <Button variant="ghost" size="icon" className="h-9 w-9 text-slate-500 hover:text-slate-900 hover:bg-slate-100 bg-slate-50 border border-slate-200">
                <ArrowLeft className="w-5 h-5" />
              </Button>
            </Link>
            <div>
              <h1 className="font-bold text-lg text-slate-900 tracking-tight">{meeting.title}</h1>
              <div className="flex items-center text-sm text-slate-500 font-medium gap-3 mt-0.5">
                <span className="flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5" />{new Date(meeting.date).toLocaleDateString()}</span>
                <span className="flex items-center gap-1.5"><Clock className="w-3.5 h-3.5" />{meeting.duration}</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            {!isLive && isOwner && (
              <Button 
                variant={meeting.isPublic ? "default" : "outline"} 
                className={meeting.isPublic ? "bg-sky-600 hover:bg-sky-700 text-white font-medium" : "border-slate-200 text-slate-700 hover:bg-slate-50 font-medium"}
                onClick={async () => {
                  const res = await fetch(`/api/meetings/${meeting.id}/share`, { method: 'POST' })
                  if (res.ok) {
                    const data = await res.json()
                    setMeeting({...meeting, isPublic: data.isPublic})
                    navigator.clipboard.writeText(window.location.href)
                    showToast(data.isPublic ? "Public link copied to clipboard!" : "Meeting is now private.")
                  }
                }}
              >
                {meeting.isPublic ? "Shared (Copy Link)" : "Share"}
              </Button>
            )}
            {isLive && (
              <Badge variant="outline" className="animate-pulse bg-sky-50 text-sky-700 border-sky-200 px-3 py-1 font-medium">
                <Loader2 className="w-3.5 h-3.5 mr-2 animate-spin inline" />
                Simulating Capture
              </Badge>
            )}
          </div>
        </div>

        {/* Media Player Area (Strict 16:9) */}
        <div className="w-full bg-slate-900 shrink-0 flex items-center justify-center border-b border-slate-200">
          <div className="w-full max-w-5xl aspect-video relative flex items-center justify-center bg-black">
            {isLive ? (
              <div className="flex flex-col items-center text-slate-400">
                <Loader2 className="w-12 h-12 mb-5 text-sky-500 animate-spin" />
                <p className="text-xl font-bold text-white tracking-tight">Preparing your meeting capture...</p>
                <p className="text-sm mt-2 font-medium">Demo capture &middot; recording simulation</p>
              </div>
            ) : (
              <video 
                ref={videoRef}
                src={meeting.mediaUrl || "https://www.w3schools.com/html/mov_bbb.mp4"} 
                className="w-full h-full object-contain"
                onTimeUpdate={handleTimeUpdate}
                controls
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
              />
            )}
          </div>
        </div>

        {/* Transcript Area */}
        <div className="flex-1 flex flex-col min-h-0 bg-white overflow-hidden">
          <div className="px-6 py-3 border-b border-slate-200 bg-slate-50/50 flex items-center justify-between shrink-0">
            <h3 className="text-sm font-bold text-slate-700 uppercase tracking-wider">Transcript</h3>
            <Button variant="ghost" size="sm" className="h-8 text-xs font-medium text-slate-500 hover:text-slate-900 bg-white border border-slate-200 shadow-sm">
              <Search className="w-3.5 h-3.5 mr-2"/>Search
            </Button>
          </div>
          <div className="flex-1 px-6 overflow-y-auto scrollbar-thin scrollbar-thumb-slate-200">
            <div className="py-6 space-y-2 pb-32">
              {fullTranscript.length === 0 && (
                <p className="text-sm text-slate-500 text-center italic mt-10">No transcript available.</p>
              )}
              {fullTranscript.map((line, i) => {
                const isActive = !isLive && currentTime >= line.startTime && currentTime < line.endTime
                const isLast = i === fullTranscript.length - 1
                return (
                  <div 
                    key={line.id} 
                    ref={isActive || (isLive && isLast) ? activeLineRef : null}
                    onClick={() => !isLive && usePlayerStore.getState().seekTo(line.startTime)}
                    className={`group cursor-pointer p-4 rounded-xl transition-all border-l-4 ${isActive ? 'bg-sky-50/80 border-sky-500 shadow-sm' : 'border-transparent hover:bg-slate-50'}`}
                  >
                    <div className="flex items-center gap-2 mb-1.5">
                      <span className="text-xs font-bold text-slate-900">{line.speaker}</span>
                      <span className="text-xs font-medium text-slate-400">
                        {Math.floor(line.startTime / 60).toString().padStart(2, '0')}:{(Math.floor(line.startTime % 60)).toString().padStart(2, '0')}
                      </span>
                      {!isLive && isOwner && (
                        <button 
                          onClick={async (e) => {
                            e.stopPropagation();
                            const res = await fetch('/api/transcribe/highlight', {
                              method: 'POST',
                              headers: {'Content-Type': 'application/json'},
                              body: JSON.stringify({ lineId: line.id })
                            });
                            if (res.ok) {
                              const data = await res.json();
                              setFullTranscript(prev => prev.map(l => l.id === line.id ? {...l, isHighlighted: data.isHighlighted} : l));
                            }
                          }}
                          className={`transition-opacity ml-2 ${line.isHighlighted ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                        >
                          <Star className={`w-4 h-4 ${line.isHighlighted ? 'text-amber-400 fill-amber-400' : 'text-slate-300 hover:text-amber-400'}`} />
                        </button>
                      )}
                    </div>
                    <p className={`text-[15px] leading-relaxed ${isActive ? 'text-slate-900 font-medium' : 'text-slate-700'} ${line.isHighlighted ? 'bg-amber-50 px-2 py-1 -ml-2 rounded text-slate-900 font-medium' : ''}`}>
                      {line.text}
                    </p>
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      </div>

      {/* Right Column (AI Tabs) */}
      <div className="w-full md:w-[480px] bg-slate-50 flex flex-col h-full shrink-0">
        <Tabs value={activeTemplate} onValueChange={handleTemplateChange} className="flex-1 flex flex-col h-full overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-200 bg-white shrink-0">
            <TabsList className="w-full bg-slate-100 border border-slate-200 p-1 h-11">
              <TabsTrigger value="Standard" className="flex-1 text-xs font-semibold data-[state=active]:bg-white data-[state=active]:text-sky-700 data-[state=active]:shadow-sm">Summary</TabsTrigger>
              <TabsTrigger value="Executive" className="flex-1 text-xs font-semibold data-[state=active]:bg-white data-[state=active]:text-sky-700 data-[state=active]:shadow-sm">Action Items</TabsTrigger>
              <TabsTrigger value="Highlights" className="flex-1 text-xs font-semibold data-[state=active]:bg-white data-[state=active]:text-sky-700 data-[state=active]:shadow-sm flex items-center gap-1.5"><Star className="w-3.5 h-3.5" /> Highlights</TabsTrigger>
              <TabsTrigger value="Chat" className="flex-1 text-xs font-semibold data-[state=active]:bg-white data-[state=active]:text-sky-700 data-[state=active]:shadow-sm">Ask AI</TabsTrigger>
            </TabsList>
          </div>

          <div className="flex-1 overflow-y-auto scrollbar-thin scrollbar-thumb-slate-200">
            <div className="p-8">
            {activeTemplate === 'Highlights' ? (
              <div className="space-y-4">
                {fullTranscript.filter(l => l.isHighlighted).length === 0 ? (
                   <div className="text-center mt-12 px-6">
                     <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-4">
                       <Star className="w-8 h-8 text-amber-400" />
                     </div>
                     <p className="text-slate-900 font-bold mb-2">No highlights yet</p>
                     <p className="text-slate-500 text-sm leading-relaxed">Hover over important transcript lines and click the star to curate key moments here.</p>
                   </div>
                ) : (
                   fullTranscript.filter(l => l.isHighlighted).map((line, idx) => (
                      <div key={idx} className="p-5 bg-white rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:border-amber-300 hover:shadow-md transition-all" onClick={() => !isLive && usePlayerStore.getState().seekTo(line.startTime)}>
                        <p className="text-xs text-slate-500 mb-2 font-bold flex items-center gap-2">
                          <span className="text-slate-900">{line.speaker}</span>
                          <span>•</span>
                          <span>{Math.floor(line.startTime / 60).toString().padStart(2, '0')}:{(Math.floor(line.startTime % 60)).toString().padStart(2, '0')}</span>
                        </p>
                        <p className="text-[15px] text-slate-800 leading-relaxed font-medium">{line.text}</p>
                      </div>
                   ))
                )}
              </div>
            ) : activeTemplate === 'Chat' ? (
              <div className="flex flex-col h-[calc(100vh-200px)]">
                <div className="flex-1 space-y-6 mb-6 overflow-y-auto pr-2">
                  {chatMessages.length === 0 ? (
                    <div className="text-center mt-12">
                      <div className="w-16 h-16 bg-sky-50 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Bot className="w-8 h-8 text-sky-600" />
                      </div>
                      <p className="text-slate-900 font-bold mb-2">Ask Gemini</p>
                      <p className="text-slate-500 text-sm">Ask any question about the meeting context.</p>
                    </div>
                  ) : (
                    chatMessages.map((msg, idx) => (
                      <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                        <div className={`px-5 py-3 rounded-2xl max-w-[85%] text-[15px] leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-sky-600 text-white rounded-br-none' : 'bg-white border border-slate-200 text-slate-800 rounded-bl-none'}`}>
                          {msg.text}
                        </div>
                      </div>
                    ))
                  )}
                  {isChatting && (
                    <div className="flex items-start">
                      <div className="px-5 py-3 rounded-2xl bg-white border border-slate-200 text-slate-500 text-[15px] flex items-center shadow-sm rounded-bl-none">
                        <Loader2 className="w-4 h-4 mr-2 animate-spin text-sky-600" /> Analyzing transcript...
                      </div>
                    </div>
                  )}
                </div>
                <div className="flex gap-3 bg-white p-2 rounded-xl border border-slate-200 shadow-sm shrink-0">
                  <input
                    type="text"
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleChat()}
                    placeholder="Ask about the meeting..."
                    className="flex-1 bg-transparent px-3 py-2 text-[15px] text-slate-900 placeholder:text-slate-400 focus:outline-none"
                  />
                  <Button onClick={handleChat} disabled={!chatInput.trim() || isChatting} className="bg-sky-600 hover:bg-sky-700 text-white font-medium px-6">Send</Button>
                </div>
              </div>
            ) : isGenerating ? (
              <div className="space-y-6 py-4">
                <div className="flex items-center space-x-3 mb-8 bg-sky-50 p-4 rounded-xl border border-sky-100">
                  <Loader2 className="w-5 h-5 animate-spin text-sky-600" />
                  <p className="text-sm font-bold text-sky-900">Gemini is analyzing the transcript...</p>
                </div>
                <div className="h-6 bg-slate-200 rounded animate-pulse w-1/3 mb-6"></div>
                <div className="space-y-4">
                  <div className="h-4 bg-slate-100 rounded animate-pulse w-full"></div>
                  <div className="h-4 bg-slate-100 rounded animate-pulse w-[92%]"></div>
                  <div className="h-4 bg-slate-100 rounded animate-pulse w-[96%]"></div>
                </div>
                <div className="h-6 bg-slate-200 rounded animate-pulse w-1/4 mt-10 mb-6"></div>
                <div className="space-y-4">
                  <div className="h-4 bg-slate-100 rounded animate-pulse w-full"></div>
                  <div className="h-4 bg-slate-100 rounded animate-pulse w-[88%]"></div>
                </div>
              </div>
            ) : (
              <AnimatePresence mode="wait">
                <motion.div
                  key={activeTemplate}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  className="prose prose-slate prose-sm max-w-none"
                >
                  {isLive ? (
                    <div className="text-center mt-16 px-6">
                      <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Bot className="w-8 h-8 text-slate-400" />
                      </div>
                      <p className="text-slate-900 font-bold mb-2">Capture in progress</p>
                      <p className="text-slate-500 text-sm leading-relaxed">The AI summary will generate automatically the moment the meeting ends.</p>
                    </div>
                  ) : currentSummary ? (
                    <div className="space-y-4 whitespace-pre-wrap text-slate-700 leading-relaxed text-[15px]">
                      {currentSummary.contentMarkdown.split('\n').map((line: string, i: number) => {
                        if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-bold text-slate-900 mt-8 mb-4 tracking-tight">{line.replace('## ', '')}</h2>
                        if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-bold text-slate-900 mt-6 mb-3">{line.replace('### ', '')}</h3>
                        if (line.startsWith('- **')) return <li key={i} className="ml-5 list-disc mb-2"><span className="font-bold text-slate-900">{line.match(/\*\*(.*?)\*\*/)?.[1]}</span> {line.replace(/- \*\*(.*?)\*\*:/, '')}</li>
                        if (line.startsWith('- ')) return <li key={i} className="ml-5 list-disc mb-2">{line.replace('- ', '')}</li>
                        if (line.match(/^\d+\./)) return <li key={i} className="ml-5 list-decimal mb-2">{line.replace(/^\d+\.\s/, '')}</li>
                        if (line.trim() === '') return <div key={i} className="h-2" />
                        return <p key={i}>{line}</p>
                      })}
                    </div>
                  ) : (
                    <div className="text-center mt-12">
                      <p className="text-slate-500 font-medium mb-6">No summary generated yet.</p>
                      {fullTranscript.length > 0 && (
                        <Button onClick={() => handleTemplateChange(activeTemplate)} className="bg-sky-600 hover:bg-sky-700 text-white shadow-sm font-medium">Generate with Gemini</Button>
                      )}
                    </div>
                  )}
                </motion.div>
              </AnimatePresence>
            )}

            {!isGenerating && activeTemplate !== 'Chat' && meetingActionItems.length > 0 && (
              <div className="mt-12 pt-8 border-t border-slate-200">
                <h3 className="text-xs font-bold text-slate-400 mb-5 uppercase tracking-widest">Detected Action Items</h3>
                <div className="space-y-4">
                  {meetingActionItems.map((item: any) => (
                    <div key={item.id} className={`flex items-start space-x-4 p-4 rounded-xl border transition-all shadow-sm ${item.isCompleted ? 'bg-slate-50 border-slate-200' : 'bg-white border-slate-200 hover:border-sky-300'}`}>
                      <Checkbox 
                        id={item.id} 
                        checked={item.isCompleted} 
                        onCheckedChange={async (checked) => {
                          const isCompleted = checked === true;
                          setMeetingActionItems(prev => prev.map(a => a.id === item.id ? { ...a, isCompleted } : a))
                          try {
                            await fetch(`/api/action-items/${item.id}`, {
                              method: 'PUT',
                              headers: { 'Content-Type': 'application/json' },
                              body: JSON.stringify({ isCompleted })
                            })
                          } catch (e) {
                            console.error(e)
                          }
                        }}
                        className="mt-1 border-slate-300 data-[state=checked]:bg-sky-600 data-[state=checked]:border-sky-600" 
                      />
                      <div className="grid gap-1.5 flex-1 pt-0.5">
                        <label htmlFor={item.id} className={`text-[15px] font-medium leading-snug cursor-pointer transition-colors ${item.isCompleted ? 'text-slate-400 line-through' : 'text-slate-900'}`}>
                          {item.task}
                        </label>
                        <p className="text-xs text-sky-600 font-bold">{item.assignee}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
            </div>
          </div>
        </Tabs>
      </div>
    </div>
  )
}

